import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty, active)
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0

    def add_to_book(oid, side, price, qty):
        nonlocal seq_counter
        seq_counter += 1
        seq = seq_counter
        orders_info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def try_match(current_id, incoming_side, incoming_price, incoming_qty, is_market):
        remaining = incoming_qty
        if incoming_side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            top = heap[0]
            if incoming_side == 'buy':
                price, seq, oid = top
            else:
                negprice, seq, oid = top
                price = -negprice

            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue

            if not is_market:
                if incoming_side == 'buy' and price > incoming_price:
                    break
                if incoming_side == 'sell' and price < incoming_price:
                    break

            trade_qty = min(remaining, info['qty'])
            if incoming_side == 'buy':
                trades.append([current_id, oid, price, trade_qty])
            else:
                trades.append([oid, current_id, price, trade_qty])

            info['qty'] -= trade_qty
            remaining -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(heap)
            # else partial fill on resting order, remains at front, loop will end since remaining==0 typically

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = try_match(oid, side, price, qty, False)
            if remaining > 0:
                add_to_book(oid, side, price, remaining)
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = try_match(oid, side, price, qty, False)
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = try_match(oid, side, None, qty, True)
            orders_info[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False}

    return trades

